import {guestLines} from './guest-lines.a5f323630eca.mjs';
export class GuestState {
 constructor(personality=0){this.frustration=0;this.leaving=false;this.gone=false;this.leaveAge=0;this.personality=personality%guestLines.length;this.eatSeconds=[24,38,30][this.personality];this.drinkSeconds=[28,20,36][this.personality];this.drinkDelay=0;this.lineCounts={};this.coolStage=null;this.heat=0;this.displayHeat=0;this.everHot=false;this.pancakes=0;this.cup=0;this.soys=0;this.say('order');this.reaction='idle';this.reactionTime=0;}
 say(event){if((this.leaving||this.gone)&&event!=='leave')return;const lines=guestLines[this.personality][event];if(!lines)return;const count=this.lineCounts[event]||0;const emoji={order:'😋',spicy:'🌶️🥵',hot:'🥵',head:'😵‍💫',plate:'🤩',floor:'🥲',warm:'😮‍💨',almost:'🌬️',cooled:'🥰',full:'🥛',refill:'😋',burnt:'🫣',raw:'😴',plain:'🤨',leave:'😤👋'};this.line=lines[count%lines.length]+' '+(emoji[event]||'');this.lineTime=3;this.lineCounts[event]=count+1;}
 offend(){if(this.leaving||this.gone)return;this.frustration++;if(this.frustration>=4){this.leaving=true;this.leaveAge=0;this.say('leave');}}
 meal(quality,spicy=false){if(this.leaving||this.gone)return;if(quality||spicy){if(spicy)this.spicy();else{this.say(quality);this.reaction='pancake_hit';this.reactionTime=2.6;this.offend();}}else this.frustration=Math.max(0,this.frustration-1);}
 hot(){if(this.leaving||this.gone)return;this.offend();this.heat=1;this.displayHeat=1;this.everHot=true;this.coolStage=null;this.say('hot');this.reaction='soy_splash';this.reactionTime=2.6;}
 spicy(){this.hot();this.say('spicy');}
 cool(seconds){if(this.gone||this.leaving||this.heat<=0)return false;this.heat=Math.max(0,this.heat-Math.max(0,seconds)/2.2);if(this.heat<.00001)this.heat=0;if(!this.heat){this.frustration=Math.max(0,this.frustration-.5);this.say('cooled');this.reaction='celebrate';this.reactionTime=2.5;}else {const stage=this.heat>.5?'warm':'almost';if(stage!==this.coolStage){this.coolStage=stage;this.say(stage);}}return !this.heat;}

 pancake(hit){if(this.leaving||this.gone)return;if(hit==='plate'){this.pancakes++;this.say('plate');this.reaction='celebrate';}else if(hit==='person'){this.hot();this.say('head');this.reaction='pancake_hit';}else{this.say('floor');this.reaction='pancake_hit';}this.reactionTime=2.6;}
 pour(dt){if(this.leaving||this.gone)return false;this.drinkDelay=1.5;const before=this.cup;this.cup=Math.min(1,this.cup+dt*.60);if(before<1&&this.cup>=1){this.soys++;this.say('full');this.reaction='celebrate';this.reactionTime=2.5;}return this.cup>=1;}
 drink(){if(this.cup>=1){this.cup=0;this.say('refill');}}
 tick(dt){if(this.leaving){this.leaveAge+=dt;if(this.leaveAge>=3.8){this.gone=true;this.heat=this.displayHeat=0;this.lineTime=0;}}this.lineTime=Math.max(0,this.lineTime-dt);const drinkTime=Math.max(0,dt-this.drinkDelay);this.drinkDelay=Math.max(0,this.drinkDelay-dt);this.cup=Math.max(0,this.cup-drinkTime/this.drinkSeconds);this.displayHeat+=(this.heat-this.displayHeat)*(1-Math.exp(-dt*14));if(this.heat===0&&this.displayHeat<.002)this.displayHeat=0;this.reactionTime=Math.max(0,this.reactionTime-dt);if(!this.reactionTime)this.reaction='idle';}
}
export function landingAt(point,guests=null){for(let i=0;i<3;i++){if(guests?.[i]?.leaving||guests?.[i]?.gone)continue;const x=(i-1)*2.5;if(((point.x-(x-.12))/.58)**2+((point.y+.9)/.55)**2<=1)return {kind:'plate',index:i};if(Math.abs(point.x-x)<.65&&point.y>-.34&&point.y<.58)return{kind:'person',index:i};}return {kind:'floor',index:Math.max(0,Math.min(2,Math.round(point.x/2.5)+1))};}
